insert into public.books (id, title, author, isbn, cover_hue) values
  ('d7f76860-2300-4fe3-b9c5-bc9bdc7beecd', 'Sapiens', 'Yuval Noah Harari', '9780062316097', 65),
  ('d6b7241d-ac32-44b6-be99-997e6f18a87a', 'Principles', 'Ray Dalio', '9781501124020', 225),
  ('50c0fe45-63f9-4136-bf51-847fd00375e7', 'Conscious Business', 'Fred Kofman', '9781591795179', 345),
  ('ddf5d78c-73c7-4c60-b981-6daae582ef17', 'The Intelligent Investor', 'Benjamin Graham', '9780060555665', 110),
  ('a54b746f-1766-4957-93cf-d45c8030ee42', 'Start with Why', 'Simon Sinek', '9781591846444', 255)
insert into public.ideas (id, book_id, topic_id, title, explanation) values
  ('0a246876-a846-4d69-9878-b6cca9c49e38', 'd7f76860-2300-4fe3-b9c5-bc9bdc7beecd', '4ce51636-bbbf-45da-95b9-a3eaa68bba7d', 'Shared stories let strangers cooperate', 'Chimpanzees can only cooperate with animals they know personally. Humans can work with millions of strangers because we believe in the same imagined things: gods, nations, companies, laws. None of these exist outside our shared stories, yet they let us organise at a scale no other species has reached.'),
  ('aab93a5e-cbba-4977-a047-92f691115b26', 'd7f76860-2300-4fe3-b9c5-bc9bdc7beecd', '4ce51636-bbbf-45da-95b9-a3eaa68bba7d', 'Humans once lived alongside other humans', 'For most of our past, Homo sapiens was not alone. Neanderthals, Homo erectus and several other human species lived at the same time. The idea that we are the only humans is recent, and how the others vanished, through competition, interbreeding or violence, is still debated.'),
  ('88566ec2-c3e2-46bf-817a-9797f821e80b', 'd7f76860-2300-4fe3-b9c5-bc9bdc7beecd', '4ce51636-bbbf-45da-95b9-a3eaa68bba7d', 'Farming was a trap that looked like progress', 'The Agricultural Revolution produced more food, but not better lives for most people. Farmers worked longer than foragers, ate a narrower diet and suffered more disease. Extra food fed larger populations rather than happier ones, and once villages had grown, there was no going back.'),
  ('2b2fbf0f-2afc-40cb-92fd-7a5cf77d2ab7', 'd7f76860-2300-4fe3-b9c5-bc9bdc7beecd', 'd1925fac-85a2-4edc-9b4f-12bc368ef762', 'Our minds are built for foraging', 'For tens of thousands of years, humans lived as hunter-gatherers. Many of our instincts, such as craving sugar and fat or gossiping about others, made sense in that world. We now carry those instincts into cities and supermarkets they were never designed for.'),
  ('18379490-fe66-4017-aabb-60ad77f9fcc6', 'd7f76860-2300-4fe3-b9c5-bc9bdc7beecd', 'd085d8bd-6f6e-4576-87c0-07fecc9529e2', 'Money is trust you can carry', 'Money has no value in itself. Coins, notes and numbers on a screen work only because everyone believes everyone else will accept them. That shared belief lets complete strangers trade with each other, making money the most widely trusted system people have invented.'),
  ('159187be-7029-491c-8d8a-3a9ef664b71c', 'd7f76860-2300-4fe3-b9c5-bc9bdc7beecd', 'ff102e80-5691-4183-8cee-22930d8855f3', 'A company is a legal fiction', 'A corporation has no body, yet it can own property, borrow money and be taken to court. It exists because lawyers, judges and the public agree to treat it as a person. If its founders all died tomorrow, the company would carry on.'),
  ('f3c19341-96ee-4680-b997-34dbc7daf2af', 'd7f76860-2300-4fe3-b9c5-bc9bdc7beecd', '4ce51636-bbbf-45da-95b9-a3eaa68bba7d', 'Writing began as bookkeeping', 'The earliest writing was not poetry or law but accounting. Sumerian scribes recorded taxes, debts and harvests on clay tablets. Writing let rulers keep track of more information than any single memory could hold, which made large states and bureaucracies possible.'),
  ('5553e293-a9c5-4d30-ab00-2aa4bb39c2d8', 'd7f76860-2300-4fe3-b9c5-bc9bdc7beecd', '6ae8f6b9-7528-4dc1-99ac-12544d0a38a3', 'Imagined orders feel natural', 'Social hierarchies, from castes to class systems, are inventions, yet the people living inside them usually see them as natural and inevitable. An imagined order survives because it is built into buildings, laws, education and desires, so it rarely looks imagined to anyone.'),
  ('238ee29a-542a-45d2-b71b-dacae4c3c0f9', 'd7f76860-2300-4fe3-b9c5-bc9bdc7beecd', 'd085d8bd-6f6e-4576-87c0-07fecc9529e2', 'Credit is a bet on the future', 'Modern economies run on credit: lending money today against wealth that does not yet exist. This only works when people trust that the future will be richer than the present. Belief in growth, fed by science and discovery, made that trust reasonable.'),
  ('a4d9e9c7-2c0d-4477-a9a3-df0c1cb762a6', 'd7f76860-2300-4fe3-b9c5-bc9bdc7beecd', '4ce51636-bbbf-45da-95b9-a3eaa68bba7d', 'Science began by admitting ignorance', 'Earlier traditions assumed that everything important was already known to gods or ancient sages. The Scientific Revolution started from the opposite position: we do not know, and must find out through observation and mathematics. Admitting ignorance turned out to be a source of enormous power.'),
  ('dce60dea-666d-4d49-b9a8-746c43d22d06', 'd7f76860-2300-4fe3-b9c5-bc9bdc7beecd', 'd1925fac-85a2-4edc-9b4f-12bc368ef762', 'Happiness depends on expectations', 'Despite huge gains in wealth and comfort, people today do not seem much happier than medieval peasants. Happiness depends less on objective conditions than on how they compare with what we expect. When conditions improve, expectations tend to rise with them.'),
  ('afc8384a-0605-45e2-a56d-fc8928faf05c', 'd7f76860-2300-4fe3-b9c5-bc9bdc7beecd', '4ce51636-bbbf-45da-95b9-a3eaa68bba7d', 'Empires blended cultures', 'Empires have often been brutal, but they were also powerful engines of cultural mixing. Conquered peoples adopted their rulers’ languages, religions and laws, then reshaped them. Much of what any group calls its own culture is the legacy of some past empire.'),
  ('180dcf1d-c855-4765-afb7-ca84ea81186d', 'd7f76860-2300-4fe3-b9c5-bc9bdc7beecd', '6ae8f6b9-7528-4dc1-99ac-12544d0a38a3', 'Progress has not been kind to animals', 'As humans grew more powerful, domesticated animals paid much of the price. Billions of cows, pigs and chickens now live in industrial farms, bred for traits that serve us rather than them. Counting their experience complicates any simple story of human progress.'),
  ('5c3ab8fc-4d52-42fc-b7ec-2682c37d1e78', 'd6b7241d-ac32-44b6-be99-997e6f18a87a', '770b67f5-8633-4425-a533-ef84544e83d8', 'Painful mistakes teach the most', 'Painful moments carry the most useful lessons, if you stop to examine them instead of avoiding them. Each mistake points at a weakness in how you think or work. Reflecting on it honestly turns a bad experience into a better approach for next time.'),
  ('bf913ed9-1e36-4762-b43e-4a679b1052c4', 'd6b7241d-ac32-44b6-be99-997e6f18a87a', '770b67f5-8633-4425-a533-ef84544e83d8', 'Face reality as it is', 'Good decisions start with seeing the world as it is, not as you want it to be. Wishful thinking feels comfortable but leads to plans built on false assumptions. The more willing you are to face unpleasant facts, the better your choices become.'),
  ('04f1e259-8618-4916-8549-607f8b1cb71b', 'd6b7241d-ac32-44b6-be99-997e6f18a87a', '75319d53-f4e2-4686-95ac-02f50013868f', 'Radical transparency builds trust', 'When people can see how decisions are made and hear honest criticism openly, there is less room for politics and hidden agendas. It feels uncomfortable at first. Over time, a team that shares everything learns faster, because problems surface early instead of festering.'),
  ('0771c26b-b3cf-4ae0-9f76-a0c635c46ebe', 'd6b7241d-ac32-44b6-be99-997e6f18a87a', '770b67f5-8633-4425-a533-ef84544e83d8', 'Weigh opinions by believability', 'Not every view deserves equal weight. Give more weight to people who have repeatedly succeeded at the thing in question and who can explain their reasoning clearly. Combining those believable opinions usually beats both a single boss’s call and a simple majority vote.'),
  ('cfcedb04-1cdb-42cd-b72f-72ef0a96caad', 'd6b7241d-ac32-44b6-be99-997e6f18a87a', 'd1925fac-85a2-4edc-9b4f-12bc368ef762', 'Your ego gets in the way', 'Two barriers block good thinking: the ego, which treats disagreement as an attack, and blind spots, which hide what others see easily. Asking how you might be wrong, rather than defending yourself, turns every disagreement into a chance to learn something.'),
  ('05aa7710-efae-46cc-bd10-eae77cdbb6ea', 'd6b7241d-ac32-44b6-be99-997e6f18a87a', 'ff102e80-5691-4183-8cee-22930d8855f3', 'An organisation is a machine', 'Think of a team as a machine, made of culture and people, that produces outcomes. When the results are poor, don’t just patch the output. Look at the design of the machine and at the people in it, and change whichever part is causing the problem.'),
  ('68be496a-c41b-4d82-b17d-1b9b667ef8e3', 'd6b7241d-ac32-44b6-be99-997e6f18a87a', '770b67f5-8633-4425-a533-ef84544e83d8', 'Progress follows five steps', 'Set clear goals, identify the problems in the way, diagnose their root causes, design a plan to remove them, then do the work. Most people skip steps, especially diagnosis, and then wonder why they keep running into the same obstacles.'),
  ('eb4d7eef-9686-4e4d-b0c1-cdd90dc1d38b', 'd6b7241d-ac32-44b6-be99-997e6f18a87a', 'e381e88e-bc00-45c4-99e8-1a14324d9ac4', 'Disagree to find the truth', 'In a disagreement, the goal is not to win but to find out what is true. Stay open to the possibility that the other person sees something you missed, and be assertive enough to say what you see. Holding both attitudes at once leads to better answers.'),
  ('f911ae4b-c614-40f8-bd6b-1c22dfac98e4', 'd6b7241d-ac32-44b6-be99-997e6f18a87a', '770b67f5-8633-4425-a533-ef84544e83d8', 'Diagnose before you fix', 'When something goes wrong, the urge is to jump straight to a solution. First find the root cause: was the plan badly designed, or was someone unable or unwilling to do their part? A problem fixed without a diagnosis tends to come back.'),
  ('8643806b-6259-4538-b0dd-0048143e5122', 'd6b7241d-ac32-44b6-be99-997e6f18a87a', '75319d53-f4e2-4686-95ac-02f50013868f', 'Hire for values first', 'Skills can be taught, but values and character are much harder to change. Look first for people who share your values, then check that they have the abilities the role needs. Putting the right people in the right roles matters more than almost anything else.'),
  ('1ec63a9c-c448-49bb-b776-ec10b30ce953', 'd6b7241d-ac32-44b6-be99-997e6f18a87a', '770b67f5-8633-4425-a533-ef84544e83d8', 'Every decision is a bet', 'Since the future is uncertain, every decision is a bet. Think about the range of possible outcomes and how likely each one is, not only the one you hope for. A good bet can still lose, so judge decisions by their reasoning, not just their results.'),
  ('9b148505-5f1c-411a-8e77-3967262a49fa', 'd6b7241d-ac32-44b6-be99-997e6f18a87a', 'd1925fac-85a2-4edc-9b4f-12bc368ef762', 'Minds are wired differently', 'Some people see the big picture, others notice detail; some are moved by logic, others by feeling. Understanding your own tendencies, and those of the people around you, helps you play to your strengths and find help where you are weak.'),
  ('249b75fd-d8e7-4674-95b1-72ded8717ac7', 'd6b7241d-ac32-44b6-be99-997e6f18a87a', 'ff102e80-5691-4183-8cee-22930d8855f3', 'Written principles speed up decisions', 'Most situations are another instance of something that has happened before. When you write down how you handled a type of situation and why, you create a principle you can reuse. Over time, these principles let you decide faster and more consistently.'),
  ('bad3d92e-6e47-4400-8637-5be1e4132027', '50c0fe45-63f9-4136-bf51-847fd00375e7', '75319d53-f4e2-4686-95ac-02f50013868f', 'Be a player, not a victim', 'When something goes wrong, you can blame circumstances or ask what you could have done differently. Blaming feels better because it protects your innocence, but it leaves you powerless. Taking responsibility for your response gives you the ability to change what happens next.'),
  ('e87a7278-f318-402e-94f0-cfc13efd86e6', '50c0fe45-63f9-4136-bf51-847fd00375e7', '6ae8f6b9-7528-4dc1-99ac-12544d0a38a3', 'Responsibility is not guilt', 'Being responsible means recognising that you can respond to a situation, not that everything is your fault. Guilt looks backwards and punishes. Responsibility looks forwards and asks what you can do now, which makes it a source of freedom rather than a burden.'),
  ('ccea110a-71f3-4fc7-a4b7-dc69ceb1f9bf', '50c0fe45-63f9-4136-bf51-847fd00375e7', 'e381e88e-bc00-45c4-99e8-1a14324d9ac4', 'Separate facts from opinions', 'Many arguments stall because people present opinions as if they were facts. Saying a colleague is lazy is a judgement; saying they missed three deadlines is an observation. Separating the two lets others check your evidence and engage with your conclusion instead of resisting it.'),
  ('212f7c34-cdb4-45d2-af39-3cf298531fff', '50c0fe45-63f9-4136-bf51-847fd00375e7', 'e381e88e-bc00-45c4-99e8-1a14324d9ac4', 'Listen to understand, not to reply', 'Most people listen while preparing their answer. Real listening means trying to grasp what the other person means and feels, then checking whether you understood. People who feel heard become far more willing to consider a different point of view.'),
  ('13ecc8b1-2481-4e1e-a869-afaa4b532a1f', '50c0fe45-63f9-4136-bf51-847fd00375e7', 'e381e88e-bc00-45c4-99e8-1a14324d9ac4', 'Turn complaints into requests', 'A complaint describes what is wrong and leaves the other person guessing what you want. A clear request says what you need, from whom and by when. It turns frustration into something the other person can accept, decline or negotiate.'),
  ('93a67021-d306-4acc-806f-4270dbe1aa67', '50c0fe45-63f9-4136-bf51-847fd00375e7', '75319d53-f4e2-4686-95ac-02f50013868f', 'Promises hold teams together', 'Teams work because people make commitments to each other and keep them. When a promise can no longer be kept, the responsible move is to say so early and renegotiate. Quietly breaking commitments erodes trust faster than any honest piece of bad news.'),
  ('77c48dd4-5e06-4e8a-ac60-4451563ec1c7', '50c0fe45-63f9-4136-bf51-847fd00375e7', '6ae8f6b9-7528-4dc1-99ac-12544d0a38a3', 'Integrity is the success you control', 'Winning matters, but outcomes are never fully in your control. Acting with integrity, true to your values, is something you can always choose. Treating that as the real measure of success brings a calm that often helps you perform better when the stakes are high.'),
  ('d4b78cea-b732-48e7-8675-e3e35aa7663a', '50c0fe45-63f9-4136-bf51-847fd00375e7', 'ff102e80-5691-4183-8cee-22930d8855f3', 'A mission makes work meaningful', 'People give their best when they see how their work serves a purpose larger than themselves. A clear mission connects daily tasks to something worth caring about, which motivates more reliably than money or fear. Leaders can make that connection visible.'),
  ('85de7cc8-5620-462c-bf03-a68a17ee2724', '50c0fe45-63f9-4136-bf51-847fd00375e7', 'd1925fac-85a2-4edc-9b4f-12bc368ef762', 'Emotions carry information', 'Feelings are not obstacles to clear thinking but signals about what matters to us. Anger points to a value that feels threatened, fear to a risk, sadness to a loss. Naming emotions, rather than suppressing them, makes it easier to respond wisely.'),
  ('a9760e5d-bb6a-462b-a472-ab16415423ba', '50c0fe45-63f9-4136-bf51-847fd00375e7', 'e381e88e-bc00-45c4-99e8-1a14324d9ac4', 'Look beneath positions to interests', 'Conflicts look like clashes of positions: I want this, you want that. Underneath are interests, the reasons behind each position, and these are often compatible. Asking why the other person wants what they want opens solutions neither side saw at the start.'),
  ('06606ca6-e39e-4cd1-9b7a-60061cf3efce', '50c0fe45-63f9-4136-bf51-847fd00375e7', '6ae8f6b9-7528-4dc1-99ac-12544d0a38a3', 'Accept what is, then act', 'Resisting reality only adds suffering to pain. Acceptance does not mean approving of a situation or giving up; it means acknowledging what is, so you can choose a useful response. Energy spent wishing things were different is energy not spent improving them.'),
  ('8d4a2b5c-771e-4a60-9b35-e4603a4210c4', '50c0fe45-63f9-4136-bf51-847fd00375e7', '75319d53-f4e2-4686-95ac-02f50013868f', 'Commitment can’t be ordered', 'Authority can force compliance, but it cannot create commitment. People commit when they understand the goal and choose to contribute. Leaders who explain their reasoning and invite participation get effort and creativity that orders never could.'),
  ('2f6a8d3a-c4cb-42fb-9b87-0659e871c00f', 'ddf5d78c-73c7-4c60-b981-6daae582ef17', '445168a4-60a9-4990-9d98-94a0df9f24a1', 'Investing is not speculating', 'Investing means studying a business first and expecting to keep your money safe while earning a modest return. Buying because a price might rise is something else: speculation. Speculating can be fine in small doses, but calling it investing hides how much risk you are taking.'),
  ('0ceb060d-75b6-4cef-abf1-f58f26f97580', 'ddf5d78c-73c7-4c60-b981-6daae582ef17', '445168a4-60a9-4990-9d98-94a0df9f24a1', 'Mr Market is moody', 'Imagine a business partner who offers every day to buy your share or sell you his. Some days he is euphoric and asks absurd prices; other days he is gloomy and sells cheaply. You can use his moods to your advantage, but you never have to follow them.'),
  ('eaf5e9af-fa6b-4301-af49-5268226a71e8', 'ddf5d78c-73c7-4c60-b981-6daae582ef17', '445168a4-60a9-4990-9d98-94a0df9f24a1', 'Demand a margin of safety', 'Buy only when the price is well below what you estimate the business is worth. The gap protects you from errors in your analysis, from bad luck and from an unknowable future. The bigger the margin, the less you need to be right.'),
  ('b7eb2b12-3710-4169-bd3b-f3bc34b10ba5', 'ddf5d78c-73c7-4c60-b981-6daae582ef17', 'd1925fac-85a2-4edc-9b4f-12bc368ef762', 'Your own behaviour is the biggest risk', 'Markets swing, but the larger danger is how people react to the swings: buying in excitement, selling in panic, chasing whatever has recently risen. Over the long run, keeping your emotions in check does more for your results than extra intelligence or information.'),
  ('e5bc014f-b005-495c-866b-e2a903106704', 'ddf5d78c-73c7-4c60-b981-6daae582ef17', '445168a4-60a9-4990-9d98-94a0df9f24a1', 'Price is not value', 'A share’s price is what someone will pay for it today; its value depends on the business’s earnings, assets and prospects. The two can drift far apart for long periods. An investor’s job is to notice the gap, not to predict the next price move.'),
  ('711ff167-69be-4cc4-a61d-4799a77a40f3', 'ddf5d78c-73c7-4c60-b981-6daae582ef17', '445168a4-60a9-4990-9d98-94a0df9f24a1', 'Your effort should set your strategy', 'There are two honest ways to invest. The defensive investor wants safety and little effort, so keeps to a simple, diversified portfolio. The enterprising investor puts in serious work for extra return. Trouble comes from wanting enterprising results with defensive effort.'),
  ('e599c461-1e55-4e73-afd7-68f3f5e9dc91', 'ddf5d78c-73c7-4c60-b981-6daae582ef17', '445168a4-60a9-4990-9d98-94a0df9f24a1', 'Keep a balance of stocks and bonds', 'A simple rule guards against overconfidence: keep between a quarter and three-quarters of your money in stocks, the rest in bonds, and rebalance when markets move. It forces you to sell some of what has risen and buy some of what has fallen.'),
  ('e2d9e8d1-700a-4298-b293-f682c90d02bb', 'ddf5d78c-73c7-4c60-b981-6daae582ef17', 'd085d8bd-6f6e-4576-87c0-07fecc9529e2', 'Inflation quietly eats savings', 'Money kept in cash or fixed-income assets loses purchasing power as prices rise. Over decades, even mild inflation takes a large bite. Owning part of real businesses, whose earnings can grow along with prices, is one of the better defences, though not a perfect one.'),
  ('bf080db5-65d5-41a0-a04a-cadbc57e0bcd', 'ddf5d78c-73c7-4c60-b981-6daae582ef17', '445168a4-60a9-4990-9d98-94a0df9f24a1', 'Past growth is a poor forecast', 'Investors pay high prices for companies that have grown fast, assuming the growth will continue. It often does not. Competition, size and change slow most stars down, so paying today for years of perfect future results usually ends in disappointment.'),
  ('2bdb5517-2c2a-48a7-b46c-72851460e8e4', 'ddf5d78c-73c7-4c60-b981-6daae582ef17', '445168a4-60a9-4990-9d98-94a0df9f24a1', 'Invest the same amount on a schedule', 'Putting the same sum in at regular intervals means you buy more shares when prices are low and fewer when they are high. It removes the impossible task of picking the right moment, and the temptation to keep waiting for a better one.'),
  ('0962f7ad-b657-4335-a2b7-172a0481631a', 'ddf5d78c-73c7-4c60-b981-6daae582ef17', '770b67f5-8633-4425-a533-ef84544e83d8', 'The crowd is not a guide to value', 'Whether a purchase is wise depends on the facts and the reasoning behind it, not on how many people share your view. Following the crowd feels safe, but it means buying what is popular and expensive and selling what is unloved and cheap.'),
  ('29cfe2dc-84f5-4ac8-af6b-ed7560414831', 'ddf5d78c-73c7-4c60-b981-6daae582ef17', '445168a4-60a9-4990-9d98-94a0df9f24a1', 'Think like a business owner', 'Owning a share means owning a piece of a real company. Ask whether you would be happy to own the whole business at that price, given its earnings, debts and management. Thinking like an owner calms the urge to react to every price change.'),
  ('9dd7b187-bbcc-48a0-b421-e1e6bb885ae0', 'a54b746f-1766-4957-93cf-d45c8030ee42', '75319d53-f4e2-4686-95ac-02f50013868f', 'Start with why', 'Most organisations explain what they do, then how, and rarely why. Inspiring ones reverse the order: they lead with their purpose, show how they pursue it, and only then say what they make. People are moved by the belief behind a product more than by its features.'),
  ('b23baf88-d5c9-4fd1-a0b9-987a3ec0b1df', 'a54b746f-1766-4957-93cf-d45c8030ee42', 'ff102e80-5691-4183-8cee-22930d8855f3', 'People buy why you do it', 'Customers choose brands that reflect what they believe about themselves. When a company’s purpose is clear, buying from it becomes a way of expressing identity. That bond is far stronger than an advantage in price or features, which competitors can always copy.'),
  ('3b1f6aa9-e969-4471-ad81-d142e4d7efb1', 'a54b746f-1766-4957-93cf-d45c8030ee42', 'd1925fac-85a2-4edc-9b4f-12bc368ef762', 'Decisions start in the gut', 'Feelings such as trust and loyalty are handled by parts of the brain that do not deal in words. That is why a choice can feel right long before we can explain it. Talking about purpose speaks to those feelings; a list of facts mostly does not.'),
  ('16415f21-8102-4878-a772-5d0c38f216d9', 'a54b746f-1766-4957-93cf-d45c8030ee42', 'ff102e80-5691-4183-8cee-22930d8855f3', 'Manipulation wins sales, not loyalty', 'Discounts, promotions, fear and novelty can all drive a sale. They work, but they must be repeated and they get more expensive over time. Loyalty, where people choose you even when a cheaper option exists, comes only from shared belief.'),
  ('0bcb3879-2921-4432-b5a4-8362ddf721d1', 'a54b746f-1766-4957-93cf-d45c8030ee42', 'ff102e80-5691-4183-8cee-22930d8855f3', 'A why needs discipline and consistency', 'A clear purpose is only the start. An organisation also needs the discipline to act on it through its values and processes, and the consistency to make everything it says and does reflect it. When any of the three is missing, trust weakens.'),
  ('f2e9d645-fedc-4ab1-9031-f77e79296b73', 'a54b746f-1766-4957-93cf-d45c8030ee42', '75319d53-f4e2-4686-95ac-02f50013868f', 'Leaders make people feel safe', 'People work hardest when they feel their leader has their back. Where trust is high, employees take risks, share ideas and help each other, because they are not busy protecting themselves. Creating that sense of safety is the leader’s job.'),
  ('8573b0c4-13fc-4676-9a70-4a03598a1bbd', 'a54b746f-1766-4957-93cf-d45c8030ee42', 'e381e88e-bc00-45c4-99e8-1a14324d9ac4', 'Say what you believe first', 'Messages that open with facts and features leave people unmoved. Opening with what you believe gives listeners a reason to care, and the details then become evidence. The order of a message changes how it is received, even when the content stays the same.'),
  ('a35a1cd2-4595-4bd2-bb9e-f17cb1be7ff7', 'a54b746f-1766-4957-93cf-d45c8030ee42', '75319d53-f4e2-4686-95ac-02f50013868f', 'Hire people who share your belief', 'Skilled people who join only for the salary will leave for a better offer. People who share your purpose stay through hard times and work with more care. When choosing who joins, look for belief as well as ability.'),
  ('b62a6159-e93e-4751-93b7-6b012a8e3d08', 'a54b746f-1766-4957-93cf-d45c8030ee42', 'ff102e80-5691-4183-8cee-22930d8855f3', 'Success can blur the why', 'As organisations grow, the founder’s purpose often fades. Measurement takes over, and attention slips from why the company exists to how much it sells. Many once-inspiring companies lose their way not through failure but through success.'),
  ('fc0cf061-051a-4007-8c32-513ecfe63274', 'a54b746f-1766-4957-93cf-d45c8030ee42', 'e381e88e-bc00-45c4-99e8-1a14324d9ac4', 'Win the early adopters first', 'Ideas spread when they win over the minority of people who share your beliefs and like trying new things. They are the ones who persuade everyone else. Aiming at the cautious majority first wastes effort, because they wait to see what the believers do.')
